class Game extends Phaser.Game {
  constructor() {
    super({
      type: Phaser.AUTO,
      width: 800,
      height: 600,
      scene: [SceneIntro, SceneMain, SceneMainMenu, SceneScores, SceneTopScores, SecondStage, ThirdStage]
    });

    this.lastFrameTime = performance.now();
    this.frameCount = 0;
    this.fps = 0;
  }

  update(time) {
    this.frameCount++;
    const currentTime = performance.now();
    const deltaTime = currentTime - this.lastFrameTime;

    if (deltaTime >= 1000) {
      this.fps = Math.round((this.frameCount / (deltaTime / 1000)));
      document.getElementById('fps').textContent = `${this.fps} FPS`;
      this.lastFrameTime = currentTime;
      this.frameCount = 0;
    }
  }
}

#fps {
  position: fixed;
  top: 10px;
  left: 10px;
  color: white;
  background-color: black;
  padding: 5px;
  border-radius: 5px;
  font-size: 16px;
}

